// Allocate each tensor and initialize it with deterministic, finite FP16 data.
// This replay measures cycles only, so captured tensor files are unnecessary.
void* load_tensor_arg(const char* exe_path, const char* rel_path, size_t size, int arg_idx,
                      const char* dtype, const char* shape) {
    (void)exe_path;
    (void)rel_path;

    // Handle zero-size tensors (e.g., dummy bias when HAS_BIAS=False)
    if (size == 0) {
        printf("  Loaded arg[%d]: tensor shape=%s, dtype=%s, size=0 bytes (zero-size, using NULL)\n", arg_idx, shape, dtype);
        return NULL;
    }

    if (size % sizeof(uint16_t) != 0 || strstr(dtype, "float16") == NULL) {
        fprintf(stderr, "Error: unsupported performance input dtype=%s size=%zu\n", dtype, size);
        return NULL;
    }

    uint16_t* h_ptr = (uint16_t*)malloc(size);
    if (!h_ptr) {
        fprintf(stderr, "Error: host allocation failed for arg[%d]\n", arg_idx);
        return NULL;
    }

    static const uint16_t finite_fp16[] = {
        0x1400, 0x9400, 0x1800, 0x9800,
        0x1c00, 0x9c00, 0x2000, 0xa000,
    };
    uint32_t state = 0x9e3779b9u ^ ((uint32_t)arg_idx * 0x85ebca6bu);
    for (size_t index = 0; index < size / sizeof(uint16_t); ++index) {
        state = state * 1664525u + 1013904223u;
        h_ptr[index] = finite_fp16[(state >> 29) & 7u];
    }

    void* d_ptr = NULL;
    cudaError_t status = cudaMalloc(&d_ptr, size);
    if (status == cudaSuccess) {
        status = cudaMemcpy(d_ptr, h_ptr, size, cudaMemcpyHostToDevice);
    }
    free(h_ptr);
    if (status != cudaSuccess) {
        fprintf(stderr, "Error: device initialization failed for arg[%d]: %s\n",
                arg_idx, cudaGetErrorString(status));
        if (d_ptr) cudaFree(d_ptr);
        return NULL;
    }

    printf("  Initialized arg[%d]: tensor shape=%s, dtype=%s, size=%zu bytes\n",
           arg_idx, shape, dtype, size);
    return d_ptr;
}

// Helper to convert FP16 to float for comparison
float fp16_to_fp32(uint16_t h) {
    uint32_t sign = (h >> 15) & 0x1;
    uint32_t exponent = (h >> 10) & 0x1F;
    uint32_t mantissa = h & 0x3FF;

    if (exponent == 0) {
        if (mantissa == 0) {
            return sign ? -0.0f : 0.0f;
        } else {
            float val = mantissa / 1024.0f / 16384.0f;
            return sign ? -val : val;
        }
    } else if (exponent == 31) {
        if (mantissa == 0) {
            return sign ? -INFINITY : INFINITY;
        } else {
            return NAN;
        }
    } else {
        // Cast exponent to int before subtraction to avoid unsigned underflow
        float val = (1.0f + mantissa / 1024.0f) * powf(2.0f, (float)((int)exponent - 15));
        return sign ? -val : val;
    }
}

// Helper to convert BF16 to float for comparison
float bf16_to_fp32(uint16_t h) {
    uint32_t f32_bits = ((uint32_t)h) << 16;
    float result;
    memcpy(&result, &f32_bits, sizeof(float));
    return result;
}

